import{_ as d,a0 as i,w as u,s as l,I as p,x as o,ao as s,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 8 - LFCS--Managing Users and Groups File Permissions and Attributes and Enabling sudo Access on Accounts","title":"LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 8 - LFCS--Managing Users and Groups File Permissions and Attributes and Enabling sudo Access on Accounts.md","filePath":"[post].md"}'),a={name:"LFCS/Part 8 - LFCS--Managing Users and Groups File Permissions and Attributes and Enabling sudo Access on Accounts.md"};function m(c,e,g,w,L,x){const t=i("Link");return u(),l("div",null,[e[26]||(e[26]=p("h1",{id:"lfcs-系列第八講-管理用户和用户組、文件權限和屬性以及啓用賬户-sudo-訪問權限",tabindex:"-1"},[o("LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限 "),p("a",{class:"header-anchor",href:"#lfcs-系列第八講-管理用户和用户組、文件權限和屬性以及啓用賬户-sudo-訪問權限","aria-label":"Permalink to “LFCS 系列第八講：管理用户和用户組、文件權限和屬性以及啓用賬户 sudo 訪問權限”"},"​")],-1)),e[27]||(e[27]=p("p",null,"去年八月份，Linux 基金會發起了全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金會認證系統管理員）認證，旨在讓世界各地的人能夠參與到中等水平的 Linux 系統的基本管理操作的認證考試中去，這項認證包括：維護正在運行的系統和服務的能力、全面監控和分析的能力以及何時向上遊團隊請求支持的決策能力。",-1)),e[28]||(e[28]=p("p",null,[p("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-8.png",alt:"Linux Users and Groups Management"})],-1)),e[29]||(e[29]=p("p",null,[p("em",null,"第八講： Linux 基金會認證系統管理員")],-1)),e[30]||(e[30]=p("p",null,"請看以下視頻，裏邊將描述 LFCS 認證程序。",-1)),e[31]||(e[31]=p("p",null,"注：youtube視頻",-1)),e[32]||(e[32]=p("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),e[33]||(e[33]=s(`<p>本講是系列教程的第八講，在這一講中，我們將引導你學習如何在 Linux 管理用户和用户組權限的設置，這些內容是 LFCS 認證的必備知識。</p><p>由於 Linux 是一個多用户的操作系統（允許多個用户通過不同主機或者終端訪問一個獨立系統），因此你需要知道如何才能有效地管理用户：如何添加、編輯、禁用和刪除用户賬户，並賦予他們足以完成自身任務的必要權限。</p><p>（LCTT 譯註：本篇原文章節順序有誤，根據理解做了調整。）</p><h3 id="添加用户賬户" tabindex="-1">添加用户賬户 <a class="header-anchor" href="#添加用户賬户" aria-label="Permalink to “添加用户賬户”">​</a></h3><p>添加新用户賬户，你需要以 root 運行以下兩條命令中的任意一條：</p><pre><code># adduser [new_account]
# useradd [new_account]
</code></pre><p>當新用户賬户添加到系統時，會自動執行以下操作：</p><ol><li><p>自動創建用户家目錄（默認是 /home/username）。</p></li><li><p>自動拷貝下列隱藏文件到新建用户的家目錄，用來設置新用户會話的環境變量。</p><pre><code>	.bash_logout
 .bash_profile
 .bashrc
</code></pre></li><li><p>自動創建郵件緩存目錄 /var/spool/mail/username。</p></li><li><p>自動創建於用户名相同的用户組。</p></li></ol><p>####理解 /etc/passwd 中的內容####</p><p>/etc/passwd 文件中存儲了所有用户賬户的信息，每個用户在裏邊都有一條對應的記錄，其格式（每個字段用冒號隔開）如下：</p><pre><code>[username]:[x]:[UID]:[GID]:[Comment]:[Home directory]:[Default shell]
</code></pre><ul><li>字段 [username] 和 [Comment] 是不言自明的。</li><li>第二個字段中 x 表明通過用户名 username 登錄系統是有密碼保護的， 密碼保存在 /etc/shadow 文件中。</li><li>[UID] 和 [GID] 字段用整數表示，代表該用户的用户標識符和對應所在組的組標誌符。</li><li>字段 [Home directory] 為 username 用户家目錄的絕對路徑。</li><li>字段 [Default shell] 指定用户登錄系統時默認使用的 shell。</li></ul><p>####理解 /etc/group 中的內容####</p><p>/etc/group 文件存儲所有用户組的信息。每行記錄的格式如下：</p><pre><code>[Group name]:[Group password]:[GID]:[Group members]
</code></pre><ul><li>[Group name] 為用户組名稱。</li><li>字段 [Group password] 為 x 的話，則説明不使用用户組密碼。</li><li>[GID] 與 /etc/passwd 中保存的 GID 相同。</li><li>[Group members] 用户組中的用户使用逗號隔開。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/add-user-accounts.png" alt="Add User Accounts in Linux"></p><p><em>添加用户賬户</em></p><h4 id="修改用户信息" tabindex="-1">修改用户信息 <a class="header-anchor" href="#修改用户信息" aria-label="Permalink to “修改用户信息”">​</a></h4><p>添加用户賬户之後，你可以使用 usermod 命令來修改用户信息中的部分字段，該命令基本語法如下：</p><pre><code># usermod [options] [username]
</code></pre><p><strong>設置賬户的過期時間</strong></p><p>通過 –expiredate 標記後邊接 年-月-日 格式的日期，如下：</p><pre><code># usermod --expiredate 2014-10-30 tecmint
</code></pre><p><strong>將用户添加到其他組</strong></p><p>使用 -aG 或者 –append –groups 選項，後邊跟着用户組，如果有多個用户組，每個用户組之間使用逗號隔開。</p><pre><code># usermod --append --groups root,users tecmint
</code></pre><p><strong>改變用户家目錄的默認位置</strong></p><p>使用 -d 或者 –home 選項，後邊跟着新的家目錄的絕對路徑。</p><pre><code># usermod --home /tmp tecmint
</code></pre><p><strong>改變用户的默認 shell</strong></p><p>使用 –shell 選項，後邊跟着新 shell 的路徑。</p><pre><code># usermod --shell /bin/sh tecmint
</code></pre><p>下面，我們一次運行上述命令：</p><pre><code># usermod --expiredate 2014-10-30 --append --groups root,users --home /tmp --shell /bin/sh tecmint
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/usermod-command-examples.png" alt="usermod Command Examples"></p><p><em>usermod 命令例示</em></p><p>擴展閲讀</p>`,38)),p("ul",null,[p("li",null,[n(t,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:r(()=>[...e[0]||(e[0]=[o("15 useradd Command Examples in Linux",-1)])]),_:1})]),p("li",null,[n(t,{href:"http://www.tecmint.com/usermod-command-examples/"},{default:r(()=>[...e[1]||(e[1]=[o("15 usermod Command Examples in Linux",-1)])]),_:1})])]),e[34]||(e[34]=s(`<p>####鎖定和解鎖賬户####</p><p>對於已有用户賬户，我們還可以：</p><p><strong>通過鎖定密碼來禁用賬户</strong></p><p>使用 -L （大寫 l）或者 –lock 選項來鎖定用户密碼。</p><pre><code># usermod --lock tecmint
</code></pre><p><strong>解鎖用户密碼</strong></p><p>使用 –u 或者 –unlock 選項來解鎖我們之前鎖定的賬户。</p><pre><code># usermod --unlock tecmint
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/lock-user-in-linux.png" alt="Lock User in Linux"></p><p><em>鎖定用户賬户</em></p><p>####刪除用户賬户####</p><p>你可以通過 userdel --remove 命令來刪除用户賬户。這樣會刪除用户擁有的家目錄和家目錄下的所有文件，以及郵件緩存目錄。</p><pre><code># userdel --remove [username]
</code></pre><h4 id="用户組管理" tabindex="-1">用户組管理 <a class="header-anchor" href="#用户組管理" aria-label="Permalink to “用户組管理”">​</a></h4><p>每次添加新用户，系統會為該用户創建同名的用户組，此時用户組裏邊只有新建的用户，其他用户可以隨後添加進去。建立用户組的目的之一，就是為了通過對指定資源設置權限來完成對這些資源和文件進行訪問控制。</p><p>比如，你有下列用户：</p><ul><li>user1 (主組 user1)</li><li>user2 (主組 user2)</li><li>user3 (主組 user3)</li></ul><p>他們都需要對你係統裏邊某個位置的 common.txt 文件，或者 user1 用户剛剛創建的共享進行讀寫。你可能會運行下列命令：</p><pre><code># chmod 660 common.txt
或
# chmod u=rw,g=rw,o= common.txt [注意最後那個 = 號和文件名之間的空格]
</code></pre><p>然而，這樣僅僅給文件所屬的用户和用户組（本例為 user1）成員的提供了讀寫權限。你還需要將 user2 和 user3 添加到 user1 組，打這樣做也將 user1 用户和用户組的其他文件的權限開放給了 user2 和 user3。</p><p>這時候，用户組就派上用場了，下面將演示怎麼做。</p><p><strong>顯示用户所屬的用户組</strong></p><pre><code># groups tecmint
# id tecmint
</code></pre><p><strong>為需要對指定文件進行讀寫的多個用户建立用户組</strong></p><p>運行下列幾條命令來完成：</p><pre><code># groupadd common_group # 添加新用户組
# chown :common_group common.txt # 將 common.txt 的用户組修改為 common_group
# usermod -aG common_group user1 # 添加用户 user1 到 common_group 用户組
# usermod -aG common_group user2 # 添加用户 user2 到 common_group 用户組
# usermod -aG common_group user3 # 添加用户 user3 到 common_group 用户組
</code></pre><p>####刪除用户組####</p><p>通過以下命令刪除用户組：</p><pre><code># groupdel [group_name]
</code></pre><p>屬於這個 group_name 用户組的文件是不會被刪除的，而僅僅是刪除了用户組。</p><h3 id="linux-文件權限" tabindex="-1">Linux 文件權限 <a class="header-anchor" href="#linux-文件權限" aria-label="Permalink to “Linux 文件權限”">​</a></h3>`,31)),p("p",null,[e[3]||(e[3]=o("除了我們在 ",-1)),n(t,{href:"https://linux.cn/article-7171-1.html"},{default:r(()=>[...e[2]||(e[2]=[o("LFCS 系列第三講：歸檔/壓縮文件及目錄、設置文件屬性和搜索文件",-1)])]),_:1}),e[4]||(e[4]=o(" 中説到的基本的讀取、寫入和執行權限外，文件還有一些不常用卻很重要的的權限設置，有時候把它當做“特殊權限”。",-1))]),e[35]||(e[35]=s(`<p>就像之前我們討論的基本權限，這裏同樣使用八進制數字或者一個字母（象徵性符號）表示該權限類型。</p><p><strong>理解 Setuid 位</strong></p><p>當為可執行文件設置 setuid 位之後，用户運行程序時會繼承該程序屬主的有效特權。由於這樣做會引起安全風險，因此設置 setuid 權限的文件及程序必須儘量少。你會發現，當系統中有用户需要訪問屬於 root 用户的文件是所運行的程序就帶有了 setuid 權限。</p><p>也就是説，用户不僅僅可以運行這個可執行文件，而且能以 root 權限來運行。比如，讓我們來看看 /bin/passwd 的權限，這個可執行文件用於改變賬户的密碼，修改 /etc/shadow 文件。超級用户可以改變任意賬户的密碼，但是其他用户只能改變自己賬户的密碼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/passwd-command.png" alt="passwd Command Examples"></p><p><em>passwd 命令例示</em></p><p>因此，所有用户都有權限運行 /bin/passwd，但只有 root 用户可以指定改變指定用户賬户的密碼。其他用户只能改變其自身的密碼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/change-user-password.png" alt="Change User Password in Linux"></p><p><em>修改用户密碼</em></p><pre><code># chmod o+u [filename]
</code></pre><p>以八進制形式來設置 setuid 位，在當前基本權限（或者想要設置的權限）前加上數字 4 就行了。</p><pre><code># chmod 4755 [filename]
</code></pre><p><strong>理解 Setgid 位</strong></p><p>設置 setgid 位之後，真實用户的有效 GID 變為屬組的 GID。因此，任何用户都能以屬組用户的權限來訪問文件。另外，當目錄置了 setgid 位之後，新建的文件將繼承其所屬目錄的 GID，並且新建的子目錄會繼承父目錄的 setgid 位。通過這個方法，你能夠以一個指定的用户組身份來訪問該目錄裏邊的文件，而不必管文件屬主的主屬組。</p><pre><code># chmod g+s [filename]
</code></pre><p>以八進制形式來設置 setgid 位，在當前基本權限（或者想要設置的權限）前加上數字 2 就行了。</p><pre><code># chmod 2755 [filename]
</code></pre><p><strong>給目錄設置 Setgid 位</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/add-setgid-to-directory.png" alt="Add Setgid in Linux"></p><p><em>給命令設置 setgid 位</em></p><p><strong>理解黏連（Sticky）位</strong></p><p>文件設置了黏連（Sticky）位是沒有意義，Linux 會忽略該位。如果設置到目錄上，會防止其內的文件被刪除或改名，除非你是該目錄或文件的屬主、或者是 root 用户。</p><pre><code># chmod o+t [directory]
</code></pre><p>以八進制形式來設置 sticky 位，在當前基本權限（或者想要設置的權限）前加上數字 1 就行了。</p><pre><code># chmod 1755 [directory]
</code></pre><p>若沒有黏連位，任何有權限讀寫目錄的用户都可刪除和重命名其中的文件。因此，黏連位通常出現在像 /tmp 之類的目錄，這些目錄是所有人都具有寫權限的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/add-sticky-bit-to-directory.png" alt="Add Stickybit in Linux"></p><p><em>給目錄設置黏連位</em></p><h3 id="linux-特殊文件屬性" tabindex="-1">Linux 特殊文件屬性 <a class="header-anchor" href="#linux-特殊文件屬性" aria-label="Permalink to “Linux 特殊文件屬性”">​</a></h3>`,29)),p("p",null,[e[6]||(e[6]=o("文件還有其他一些屬性，用來做進一步的操作限制。比如，阻止對文件的重命名、移動、刪除甚至是修改。可以通過使用 ",-1)),n(t,{href:"http://www.tecmint.com/chattr-command-examples/"},{default:r(()=>[...e[5]||(e[5]=[o("chattr 命令",-1)])]),_:1}),e[7]||(e[7]=o(" 來設置，並可以使用 lsattr 工具來查看這些屬性。設置如下：",-1))]),e[36]||(e[36]=s(`<pre><code># chattr +i file1
# chattr +a file2
</code></pre><p>運行這些命令之後，file1 成為不可變狀態（即不可移動、重命名、修改或刪除），而 file2 進入“僅追加”模式（僅在追加內容模式中打開）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/chattr-command.png" alt="Protect File from Deletion"></p><p><em>通過 Chattr 命令來包含文件</em></p><h3 id="訪問-root-賬户並啓用-sudo" tabindex="-1">訪問 root 賬户並啓用 sudo <a class="header-anchor" href="#訪問-root-賬户並啓用-sudo" aria-label="Permalink to “訪問 root 賬户並啓用 sudo”">​</a></h3><p>訪問 root 賬户的方法之一，就是通過輸入：</p><pre><code>$ su
</code></pre><p>然後輸入 root 賬户密碼。</p><p>倘若授權成功，你將以 root 身份登錄，工作目錄則是登錄前所在的位置。如果是想要一登錄就自動進入 root 用户的家目錄，請運行：</p><pre><code>$ su -
</code></pre><p>然後輸入 root 賬户密碼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Enable-Sudo-Access.png" alt="switch user by su "></p><p><em>用户通過 su 切換</em></p><p>執行上個步驟需要普通用户知道 root 賬户的密碼，這樣會引起非常嚴重的安全問題。於是，系統管理員通常會配置 sudo 命令來讓普通用户在嚴格控制的環境中以其他用户身份（通常是 root）來執行命令。所以，可以在嚴格控制用户的情況下，又允許他運行一條或多條特權命令。</p>`,14)),p("ul",null,[p("li",null,[e[9]||(e[9]=o("擴展閲讀：",-1)),n(t,{href:"http://www.tecmint.com/su-vs-sudo-and-how-to-configure-sudo-in-linux/"},{default:r(()=>[...e[8]||(e[8]=[o("Difference Between su and sudo User",-1)])]),_:1})])]),e[37]||(e[37]=p("p",null,"普通用户通過他自己的用户密碼來完成 sudo 授權。輸入命令之後會出現輸入密碼（並不是超級用户密碼）的提示，授權成功（只要賦予了用户運行該命令的權限）的話，指定的命令就會運行。",-1)),e[38]||(e[38]=p("p",null,"系統管理員必須編輯 /etc/sudoers 文件，才能為 sudo 賦予相應權限。通常建議使用 visudo 命令來編輯這個文件，而不是使用文本編輯器來打開它。",-1)),e[39]||(e[39]=p("pre",null,[p("code",null,`# visudo
`)],-1)),p("p",null,[e[11]||(e[11]=o("這樣會使用 vim（你可以按照 ",-1)),n(t,{href:"https://linux.cn/article-7165-1.html"},{default:r(()=>[...e[10]||(e[10]=[o("LFCS 系列第二講：如何安裝和使用純文本編輯器 vi/vim",-1)])]),_:1}),e[12]||(e[12]=o(" 裏邊説的來編輯文件）來打開 /etc/sudoers 文件。",-1))]),e[40]||(e[40]=s(`<p>以下是需要設置的相關的行：</p><pre><code>Defaults    secure_path=&quot;/usr/sbin:/usr/bin:/sbin&quot;
root        ALL=(ALL) ALL
tecmint     ALL=/bin/yum update
gacanepa    ALL=NOPASSWD:/bin/updatedb
%admin      ALL=(ALL) ALL
</code></pre><p>來更加深入瞭解這些項：</p><pre><code>Defaults    secure_path=&quot;/usr/sbin:/usr/bin:/sbin:/usr/local/bin&quot;
</code></pre><p>這一行指定 sudo 將要使用的目錄，這樣可以阻止使用某些用户指定的目錄，那樣的話可能會危及系統。</p><p>下一行是用來指定權限的：</p><pre><code>root        ALL=(ALL) ALL
</code></pre><ul><li><p>第一個 ALL 關鍵詞表明這條規則適用於所有主機。</p></li><li><p>第二個 ALL 關鍵詞表明第一個字段中所指定的用户能以任何用户身份的權限來運行相應命令。</p></li><li><p>第三個 ALL 關鍵詞表明可以運行任何命令。</p><p>tecmint ALL=/bin/yum update</p></li></ul><p>如果 = 號後邊沒有指定用户，sudo 則默認為 root 用户。本例中，tecmint 用户能以 root 身份運行 yum update 命令。</p><pre><code>gacanepa    ALL=NOPASSWD:/bin/updatedb
</code></pre><p>NOPASSWD 關鍵詞表明 gacanepa 用户不需要密碼，可以直接運行 /bin/updatedb 命令。</p><pre><code>%admin      ALL=(ALL) ALL
</code></pre><p>% 符號表示該行應用於 admin 用户組。其他部分的含義與對於用户的含義是一樣的。本例表示 admin 用户組的成員可以通過任何主機連接來運行任何命令。</p><p>通過 sudo -l 命令可以查看，你的賬户擁有什麼樣的權限。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/sudo-access-rules.png" alt="Sudo Access Rules"></p><p><em>Sudo 訪問規則</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>對於系統管理員來説，高效能的用户和文件管理技能是非常必要的。本文已經涵蓋了這些內容，我們希望你將這些作為一個開始，然後慢慢進步。隨時在下邊發表評論或提問，我們會盡快回應的。</p><hr>`,19)),p("p",null,[e[14]||(e[14]=o("via: ",-1)),n(t,{href:"http://www.tecmint.com/manage-users-and-groups-in-linux/"},{default:r(()=>[...e[13]||(e[13]=[o("http://www.tecmint.com/manage-users-and-groups-in-linux/",-1)])]),_:1})]),p("p",null,[e[18]||(e[18]=o("作者：",-1)),n(t,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...e[15]||(e[15]=[o("Gabriel Cánepa",-1)])]),_:1}),e[19]||(e[19]=o(" 譯者：",-1)),n(t,{href:"https://github.com/GHLandy"},{default:r(()=>[...e[16]||(e[16]=[o("GHLandy",-1)])]),_:1}),e[20]||(e[20]=o(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[17]||(e[17]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[23]||(e[23]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[21]||(e[21]=[o("LCTT",-1)])]),_:1}),e[24]||(e[24]=o(" 原創翻譯，",-1)),n(t,{href:"https://linux.cn/"},{default:r(()=>[...e[22]||(e[22]=[o("Linux中國",-1)])]),_:1}),e[25]||(e[25]=o(" 榮譽推出",-1))])])}const A=d(a,[["render",m]]);export{C as __pageData,A as default};
